args:
set -ex

export PKG=github.com/docker/sandboxes/sandboxd
export VERSION=$(cat /tmp/.version)
export REVISION=$(cat /tmp/.revision)
export RELEASE=$(cat /tmp/.release)
export COMMIT_DATE=$(cat /tmp/.commit_date)
export DOCKER_NEXT_VERSION=$(cat /tmp/.docker_next_version)
export DOCKER_NEXT_COMMIT=$(cat /tmp/.docker_next_commit)
export NERDBOX_VERSION=$(cat /tmp/.nerdbox_version)
export SAILOR_COMMIT=$(cat /tmp/.sailor_commit)
LDFLAGS="-X ${PKG}/version.Version=${VERSION} -X ${PKG}/version.Revision=sbx-revision-v1:${REVISION}:sbx-revision-end -X ${PKG}/version.Package=${PKG} -X ${PKG}/version.BuildDate=${COMMIT_DATE} -X ${PKG}/version.Release=${RELEASE}"
LDFLAGS="${LDFLAGS} -X ${PKG}/version.DockerNextVersion=${DOCKER_NEXT_VERSION} -X ${PKG}/version.DockerNextCommit=${DOCKER_NEXT_COMMIT} -X ${PKG}/version.NerdboxVersion=${NERDBOX_VERSION} -X ${PKG}/version.SailorCommit=${SAILOR_COMMIT}"

echo "${LDFLAGS}" > /tmp/.ldflags
